const std = @import("std");

pub fn main() !void {
    const s1 = "ABCDGH";
    const s2 = "AEDFHR";
    var dp: [7][7]u32 = [_][7]u32{[_]u32{0} ** 7} ** 7;

    for (1..s1.len + 1) |i| {
        for (1..s2.len + 1) |j| {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = @max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    std.debug.print("LCS length: {}\n", .{dp[s1.len][s2.len]});
}

